def sheet(wb, title, header, rows, widths, judge_col=None, note=None):
    ws = wb.create_sheet(title); r0 = 1
    if note:
        ws.cell(1, 1, note).alignment = Alignment(wrap_text=True, vertical="top")
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=len(header)); ws.row_dimensions[1].height = 48; r0 = 2
    for j, h in enumerate(header, 1):
        c = ws.cell(r0, j, h); c.font = Font(bold=True, color="FFFFFF"); c.fill = HFILL; c.border = BORDER
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    for i, row in enumerate(rows, r0 + 1):
        for j, v in enumerate(row, 1):
            c = ws.cell(i, j, v); c.border = BORDER; c.alignment = Alignment(wrap_text=True, vertical="top")
            if judge_col is not None and j == judge_col + 1 and v in FILL: c.fill = PatternFill("solid", fgColor=FILL[v])
    for j, w in enumerate(widths, 1): ws.column_dimensions[get_column_letter(j)].width = w
    ws.freeze_panes = ws.cell(r0 + 1, 1)
    return ws


def run(tag, c): return G.curve(os.path.join(PRJ, "runs", f"{tag}_c{c}"))
def metrics(pts):
    k = min(range(len(pts)), key=lambda j: pts[j][1])
    v10, v8, v6 = G.cross(pts, 1e-10), G.cross(pts, 1e-8), G.cross(pts, 1e-6)
    return dict(v10=v10, v8=v8, v6=v6, ss=(v8 - v10) / 2 * 1e3, vmin=pts[k][0], lmin=math.log10(pts[k][1]), lm1=G.at(pts, -1.0), l1=G.at(pts, 1.0), l18=G.at(pts, 1.79))

